from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    results = []
    cache = OrderedDict()  # key -> (value, write_time)

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in cache:
                v, wt = cache[key]
                if t - wt >= ttl:
                    # expired, remove it
                    del cache[key]
                else:
                    # still valid, just update
                    del cache[key]
                    cache[key] = (value, t)
                    continue
            # key not present (either never was, or just removed due to expiry)
            if len(cache) >= capacity:
                cache.popitem(last=False)
            cache[key] = (value, t)
        elif op[0] == 'get':
            _, t, key = op
            if key in cache:
                v, wt = cache[key]
                if t - wt >= ttl:
                    del cache[key]
                    results.append(-1)
                else:
                    del cache[key]
                    cache[key] = (v, wt)
                    results.append(v)
            else:
                results.append(-1)

    return results

